<?php
$e=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$state=(string)($reservation['status']??'pending');
$logoPath=trim((string)($restaurant['logo_path']??''));
$logoUrl=$logoPath===''?'':(preg_match('#^https?://#i',$logoPath)?$logoPath:rtrim(BASE_URL,'/').'/'.ltrim($logoPath,'/'));
$labels=['pending'=>'Reservation request received','booked'=>'Reservation confirmed','seated'=>'Checked in','cancelled'=>'Reservation cancelled','no_show'=>'Marked as no-show'];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reservation status · <?= $e($restaurant['restaurant_name']??'Restaurant') ?></title>
<style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:22px;background:#f3f6fb;color:#182338;font:16px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif}.card{width:min(100%,480px);padding:28px;background:#fff;border:1px solid #e1e8f1;border-radius:22px;box-shadow:0 14px 40px rgba(28,49,82,.08);text-align:center}.brand-logo{display:block;width:auto;max-width:150px;height:auto;max-height:100px;object-fit:contain;margin:0 auto 12px}.badge{display:inline-block;padding:7px 12px;border-radius:999px;background:<?= $state==='booked'?'#dcfce7':($state==='cancelled'?'#fee2e2':'#fff4cf') ?>;color:<?= $state==='booked'?'#166534':($state==='cancelled'?'#991b1b':'#92400e') ?>;font-weight:800}.number{font-size:1.3rem;font-weight:800;margin:20px 0 5px}.muted{color:#66758c}.btn{display:inline-block;margin-top:18px;padding:12px 18px;border-radius:11px;background:#1769e8;color:#fff;text-decoration:none;font-weight:750}</style></head><body><main class="card"><?php if($logoUrl!==''): ?><img class="brand-logo" src="<?= $e($logoUrl) ?>" alt="<?= $e($restaurant['restaurant_name']??'Restaurant') ?> logo"><?php endif; ?><h1 style="font-size:1.5rem;margin:0"><?= $e($restaurant['restaurant_name']??'Restaurant') ?></h1><p class="muted">Reservation status</p><span class="badge"><?= $e($labels[$state]??'Reservation status') ?></span><div class="number"><?= $e(date('D, M j, Y',strtotime((string)$reservation['reservation_at']))) ?></div><div><?= $e(date('g:i A',strtotime((string)$reservation['reservation_at']))) ?> · <?= (int)$reservation['party_size'] ?> <?= (int)$reservation['party_size']===1?'guest':'guests' ?></div><?php if($state==='pending'): ?><p class="muted">The restaurant has received your request. This page will show the updated status when you refresh it.</p><?php elseif($state==='booked'): ?><p class="muted">Your reservation is confirmed. Please arrive on time and contact the restaurant if your plans change.</p><?php endif; ?><a class="btn" href="<?= $e(BASE_URL.'/reserve/'.($paramsToken??'')) ?>">Make another reservation</a></main></body></html>